                if self.peek() == '=':
                    self.advance()
                    self.tokens.append(Token('GE', '>=', line, col))
                else:
                    self.tokens.append(Token('GT', '>', line, col))
            elif ch == '.':
                self.advance()
                if self.peek() == '.':
                    self.advance()
                    self.tokens.append(Token('CONCAT', '..', line, col))
                else:
                    self.tokens.append(Token('DOT', '.', line, col))
            elif ch == '#':
                self.advance()
                self.tokens.append(Token('LEN', '#', line, col))
            elif ch == '(':
                self.advance()
                self.tokens.append(Token('LPAREN', '(', line, col))
            elif ch == ')':
                self.advance()
                self.tokens.append(Token('RPAREN', ')', line, col))
            elif ch == '{':
                self.advance()
                self.tokens.append(Token('LBRACE', '{', line, col))
            elif ch == '}':
                self.advance()
                self.tokens.append(Token('RBRACE', '}', line, col))
            elif ch == '[':
                self.advance()
                self.tokens.append(Token('LBRACKET', '[', line, col))
            elif ch == ']':
                self.advance()
                self.tokens.append(Token('RBRACKET', ']', line, col))
            elif ch == ';':
                self.advance()
                self.tokens.append(Token('SEMI', ';', line, col))
            elif ch == ',':
                self.advance()
                self.tokens.append(Token('COMMA', ',', line, col))
            elif ch == ':':
                self.advance()
                self.tokens.append(Token('COLON', ':', line, col))
            else:
                raise SyntaxError(f"Unexpected character '{ch}' at line {line}")

        self.tokens.append(Token('EOF', None))

class ASTNode:
    pass

class Chunk(ASTNode):
    def __init__(self, statements):
        self.statements = statements

class BinOp(ASTNode):
    def __init__(self, left, op, right):
        self.left = left
        self.op = op
        self.right = right

class UnaryOp(ASTNode):
    def __init__(self, op, operand):
        self.op = op
        self.operand = operand

class Number(ASTNode):
    def __init__(self, value):
        self.value = value

class String(ASTNode):
    def __init__(self, value):
        self.value = value

class Bool(ASTNode):
    def __init__(self, value):
        self.value = value

class Nil(ASTNode):
    pass

class Var(ASTNode):
    def __init__(self, name):
        self.name = name

class Assignment(ASTNode):
    def __init__(self, targets, values):
        self.targets = targets
        self.values = values

class LocalAssignment(ASTNode):
    def __init__(self, names, values):
        self.names = names
        self.values = values

class IfStatement(ASTNode):
    def __init__(self, condition, then_block, elif_blocks, else_block):
        self.condition = condition
        self.then_block = then_block
        self.elif_blocks = elif_blocks
        self.else_block = else_block

class WhileStatement(ASTNode):
    def __init__(self, condition, body):
        self.condition = condition
        self.body = body

class ForStatement(ASTNode):
    def __init__(self, var, start, end, step, body):
        self.var = var
        self.start = start
        self.end = end
        self.step = step
        self.body = body

class ForInStatement(ASTNode):
    def __init__(self, vars, expressions, body):
        self.vars = vars
        self.expressions = expressions
        self.body = body

class FunctionDef(ASTNode):
    def __init__(self, name, params, varargs, body, is_local=False):
        self.name = name
        self.params = params
        self.varargs = varargs
        self.body = body
        self.is_local = is_local

class FunctionCall(ASTNode):
    def __init__(self, func, args):
        self.func = func
        self.args = args

class MethodCall(ASTNode):
    def __init__(self, obj, method, args):
        self.obj = obj
        self.method = method
        self.args = args

class Table(ASTNode):
    def __init__(self, fields):
        self.fields = fields  # List of (key, value) or just value

class IndexAccess(ASTNode):
    def __init__(self, obj, index):
        self.obj = obj
        self.index = index

class ReturnStatement(ASTNode):
    def __init__(self, values):
        self.values = values

class BreakStatement(ASTNode):
    pass

class DoBlock(ASTNode):
    def __init__(self, body):
        self.body = body

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self, offset=0):
        pos = self.pos + offset
        if pos < len(self.tokens):
            return self.tokens[pos]
        return self.tokens[-1]  # EOF

    def advance(self):
        token = self.peek()
        if token.type != 'EOF':
            self.pos += 1
        return token

    def expect(self, type_):
        token = self.peek()
        if token.type != type_:
            raise SyntaxError(f"Expected {type_}, got {token.type} at line {token.line}")
        return self.advance()

    def match(self, *types):
        return self.peek().type in types

    def parse(self):
        statements = []
        while self.peek().type != 'EOF':
            stmt = self.parse_statement()
            if stmt:
                statements.append(stmt)
        return Chunk(statements)

    def parse_statement(self):
        if self.match('IF'):
            return self.parse_if()
        elif self.match('WHILE'):
            return self.parse_while()
        elif self.match('FOR'):
            return self.parse_for()
        elif self.match('FUNCTION'):
            return self.parse_function_def()
        elif self.match('LOCAL'):
            return self.parse_local()
        elif self.match('RETURN'):
            return self.parse_return()
        elif self.match('BREAK'):
            self.advance()
            return BreakStatement()
        elif self.match('DO'):
            return self.parse_do()
        elif self.match('REPEAT'):
            return self.parse_repeat()
        else:
            return self.parse_expression_statement()

    def parse_expression_statement(self):
        expr = self.parse_expression()

        # Check for assignment
        if self.match('ASSIGN', 'COMMA'):
            targets = [expr]
            while self.match('COMMA'):
                self.advance()
                targets.append(self.parse_expression())

            self.expect('ASSIGN')

            values = [self.parse_expression()]
            while self.match('COMMA'):
                self.advance()
                values.append(self.parse_expression())

            return Assignment(targets, values)

        return expr

    def parse_if(self):
        self.advance()  # if
        condition = self.parse_expression()
        self.expect('THEN')
        then_block = self.parse_block_until('ELSEIF', 'ELSE', 'END')

        elif_blocks = []
        while self.match('ELSEIF'):
            self.advance()
            elif_condition = self.parse_expression()
            self.expect('THEN')
            elif_body = self.parse_block_until('ELSEIF', 'ELSE', 'END')
            elif_blocks.append((elif_condition, elif_body))

        else_block = None
        if self.match('ELSE'):
            self.advance()
            else_block = self.parse_block_until('END')

        self.expect('END')
        return IfStatement(condition, then_block, elif_blocks, else_block)

    def parse_while(self):
        self.advance()  # while
        condition = self.parse_expression()
        self.expect('DO')
        body = self.parse_block_until('END')
        self.expect('END')
        return WhileStatement(condition, body)

    def parse_for(self):
        self.advance()  # for
        var = self.expect('IDENT').value

        if self.match('ASSIGN'):
            # Numeric for
            self.advance()
            start = self.parse_expression()
            self.expect('COMMA')
            end = self.parse_expression()

            step = Number(1)
            if self.match('COMMA'):
                self.advance()
                step = self.parse_expression()

            self.expect('DO')
            body = self.parse_block_until('END')
            self.expect('END')
            return ForStatement(var, start, end, step, body)
        elif self.match('IN', 'COMMA'):
            # Iterator for (can have multiple variables)
            vars = [var]
            while self.match('COMMA'):
                self.advance()
                vars.append(self.expect('IDENT').value)

            self.expect('IN')

            expressions = [self.parse_expression()]
            while self.match('COMMA'):
                self.advance()
                expressions.append(self.parse_expression())

            self.expect('DO')
            body = self.parse_block_until('END')
            self.expect('END')
            return ForInStatement(vars, expressions, body)
        else:
            raise SyntaxError("Invalid for loop")

    def parse_function_def(self):
        self.advance()  # function
        name = None
        if self.match('IDENT'):
            name = self.expect('IDENT').value

        self.expect('LPAREN')
        params = []
        varargs = False

        if not self.match('RPAREN'):
            if self.match('IDENT'):
                params.append(self.expect('IDENT').value)
                while self.match('COMMA'):
                    self.advance()
                    if self.match('IDENT'):
                        params.append(self.expect('IDENT').value)
                    elif self.peek().value == '...':
                        # varargs
                        self.advance()
                        varargs = True
                        break
            elif self.peek().value == '...':
                self.advance()
                varargs = True

        self.expect('RPAREN')
        body = self.parse_block_until('END')
        self.expect('END')
        return FunctionDef(name, params, varargs, body, False)

    def parse_local(self):
        self.advance()  # local

        names = [self.expect('IDENT').value]
        while self.match('COMMA'):
            self.advance()
            names.append(self.expect('IDENT').value)

        values = []
        if self.match('ASSIGN'):
            self.advance()
            values = [self.parse_expression()]
            while self.match('COMMA'):
                self.advance()
                values.append(self.parse_expression())

        return LocalAssignment(names, values)

    def parse_return(self):
        self.advance()  # return
        values = []
        if not self.match('EOF', 'END', 'ELSEIF', 'ELSE', 'UNTIL'):
            values = [self.parse_expression()]
            while self.match('COMMA'):
                self.advance()
                values.append(self.parse_expression())
        return ReturnStatement(values)

    def parse_do(self):
        self.advance()  # do
        body = self.parse_block_until('END')
        self.expect('END')
        return DoBlock(body)

    def parse_repeat(self):
        self.advance()  # repeat
        body = self.parse_block_until('UNTIL')
        self.expect('UNTIL')
        condition = self.parse_expression()
        # repeat-until loops until condition is true (opposite of while)
        # Convert to while not condition
        return WhileStatement(UnaryOp('not', condition), body)

    def parse_block_until(self, *terminators):
        statements = []
        while not self.match(*terminators, 'EOF'):
            stmt = self.parse_statement()
            if stmt:
                statements.append(stmt)
        return statements

    def parse_expression(self):
        return self.parse_or()

    def parse_or(self):
        left = self.parse_and()
        while self.match('OR'):
            op = self.advance().value
            right = self.parse_and()
            left = BinOp(left, 'or', right)
        return left

    def parse_and(self):
        left = self.parse_comparison()
        while self.match('AND'):
            op = self.advance().value
            right = self.parse_comparison()
            left = BinOp(left, 'and', right)
        return left

    def parse_comparison(self):
        left = self.parse_concat()
        while self.match('LT', 'GT', 'LE', 'GE', 'EQ', 'NE'):
            op = self.advance().value
            right = self.parse_concat()
            left = BinOp(left, op, right)
        return left

    def parse_concat(self):
        left = self.parse_additive()
        while self.match('CONCAT'):
            op = self.advance().value
            right = self.parse_additive()
            left = BinOp(left, '..', right)
        return left

    def parse_additive(self):
        left = self.parse_multiplicative()
        while self.match('PLUS', 'MINUS'):
            op = self.advance().value
            right = self.parse_multiplicative()
            left = BinOp(left, op, right)
        return left

    def parse_multiplicative(self):
        left = self.parse_unary()
        while self.match('STAR', 'SLASH', 'INTDIV', 'MOD'):
            op = self.advance().value
            right = self.parse_unary()
            left = BinOp(left, op, right)
        return left

    def parse_unary(self):
        if self.match('NOT', 'MINUS', 'LEN'):
            op = self.advance().value
            operand = self.parse_unary()
            return UnaryOp(op, operand)
        return self.parse_power()

    def parse_power(self):
        left = self.parse_postfix()
        if self.match('POW'):
            op = self.advance().value
            right = self.parse_power()  # Right associative
            left = BinOp(left, op, right)
        return left

    def parse_postfix(self):
        expr = self.parse_primary()

        while True:
            if self.match('LBRACKET'):
                self.advance()
                index = self.parse_expression()
                self.expect('RBRACKET')
                expr = IndexAccess(expr, index)
            elif self.match('DOT'):
                self.advance()
                field = self.expect('IDENT').value
                expr = IndexAccess(expr, String(field))
            elif self.match('COLON'):
                self.advance()
                method = self.expect('IDENT').value
                self.expect('LPAREN')
                args = self.parse_args()
                self.expect('RPAREN')
                expr = MethodCall(expr, method, args)
            elif self.match('LPAREN'):
                self.advance()
                args = self.parse_args()
                self.expect('RPAREN')
                expr = FunctionCall(expr, args)
            elif self.match('LBRACE'):
                # Table constructor as argument
                args = [self.parse_table()]
                expr = FunctionCall(expr, args)
            elif self.match('STRING'):
                # String as argument
                args = [String(self.advance().value)]
                expr = FunctionCall(expr, args)
            else:
                break

        return expr

    def parse_primary(self):
        if self.match('NUMBER'):
            value = self.advance().value
            return Number(value)
        elif self.match('STRING'):
            value = self.advance().value
            return String(value)
        elif self.match('TRUE'):
            self.advance()
            return Bool(True)
        elif self.match('FALSE'):
            self.advance()
            return Bool(False)
        elif self.match('NIL'):
            self.advance()
            return Nil()
        elif self.match('IDENT'):
            name = self.advance().value
            return Var(name)
        elif self.match('LPAREN'):
            self.advance()
            expr = self.parse_expression()
            self.expect('RPAREN')
            return expr
        elif self.match('LBRACE'):
            return self.parse_table()
        elif self.match('FUNCTION'):
            return self.parse_function_def()
        else:
            raise SyntaxError(f"Unexpected token: {self.peek()}")

    def parse_table(self):
        self.expect('LBRACE')
        fields = []

        while not self.match('RBRACE'):
            if self.match('IDENT') and self.peek(1).type == 'ASSIGN':
                # Key = value
                key = self.expect('IDENT').value
                self.expect('ASSIGN')
                value = self.parse_expression()
                fields.append((String(key), value))
            elif self.match('LBRACKET'):
                # [expr] = value
                self.advance()
                key = self.parse_expression()
                self.expect('RBRACKET')
                self.expect('ASSIGN')
                value = self.parse_expression()
                fields.append((key, value))
            else:
                # Just value
                value = self.parse_expression()
                fields.append((None, value))

            if self.match('COMMA'):
                self.advance()
            elif not self.match('RBRACE'):
                break

        self.expect('RBRACE')
        return Table(fields)

    def parse_args(self):
        args = []
        if not self.match('RPAREN', 'RBRACE'):
            args.append(self.parse_expression())
            while self.match('COMMA'):
                self.advance()
                args.append(self.parse_expression())
        return args

class LuaFunction:
    """Represents a Lua function"""
    def __init__(self, params, varargs, body, closure):
        self.params = params
        self.varargs = varargs
        self.body = body
        self.closure = closure

class LuaTable:
    """Represents a Lua table"""
    def __init__(self):
        self.dict = {}
        self.list = []

    def get(self, key):
        if isinstance(key, int):
            if 1 <= key <= len(self.list):
                return self.list[key - 1]
            return LuaNil()
        return self.dict.get(self._make_key(key), LuaNil())

    def set(self, key, value):
        if isinstance(key, int) and key > 0:
            # Extend list if needed
            while len(self.list) < key:
                self.list.append(LuaNil())
            self.list[key - 1] = value
        else:
            self.dict[self._make_key(key)] = value

    def _make_key(self, key):
        if isinstance(key, str):
            return key
        return str(key)

    def length(self):
        return len(self.list)

    def items(self):
        result = []
        for i, v in enumerate(self.list):
            result.append((i + 1, v))
        for k, v in self.dict.items():
            result.append((k, v))
        return result

class Interpreter:
    def __init__(self):
        self.globals = self._init_globals()
        self.locals_stack = [{}]  # Stack of local scopes
        self.should_return = False
        self.return_values = []
        self.should_break = False

    def _init_globals(self):
        """Initialize global environment with built-in functions"""
        globals_ = {
            'print': self._builtin_print,
            'type': self._builtin_type,
            'tonumber': self._builtin_tonumber,
            'tostring': self._builtin_tostring,
            'assert': self._builtin_assert,
            'pairs': self._builtin_pairs,
            'ipairs': self._builtin_ipairs,
            'next': self._builtin_next,
            'rawget': self._builtin_rawget,
            'rawset': self._builtin_rawset,
            'setmetatable': self._builtin_setmetatable,
            'getmetatable': self._builtin_getmetatable,
            'error': self._builtin_error,
            'select': self._builtin_select,
            'unpack': self._builtin_unpack,
            'arg': LuaTable(),  # Will be filled by interpreter
        }

        # Add math library
        globals_['math'] = self._create_math_library()
        globals_['table'] = self._create_table_library()
        globals_['string'] = self._create_string_library()

        return globals_

    def _create_math_library(self):
        math_lib = LuaTable()
        math_lib.set('pi', math.pi)
        math_lib.set('e', math.e)
        math_lib.set('sin', lambda x: math.sin(self._tonumber(x)))
        math_lib.set('cos', lambda x: math.cos(self._tonumber(x)))
        math_lib.set('tan', lambda x: math.tan(self._tonumber(x)))
        math_lib.set('sqrt', lambda x: math.sqrt(self._tonumber(x)))
        math_lib.set('floor', lambda x: math.floor(self._tonumber(x)))
        math_lib.set('ceil', lambda x: math.ceil(self._tonumber(x)))
        math_lib.set('abs', lambda x: abs(self._tonumber(x)))
        math_lib.set('min', lambda *args: min([self._tonumber(x) for x in args]))
        math_lib.set('max', lambda *args: max([self._tonumber(x) for x in args]))
        math_lib.set('pow', lambda x, y: math.pow(self._tonumber(x), self._tonumber(y)))
        math_lib.set('exp', lambda x: math.exp(self._tonumber(x)))
        math_lib.set('log', lambda x, base=math.e: math.log(self._tonumber(x), self._tonumber(base)))
        math_lib.set('rad', lambda x: math.radians(self._tonumber(x)))
        math_lib.set('deg', lambda x: math.degrees(self._tonumber(x)))
        return math_lib

    def _create_table_library(self):
        table_lib = LuaTable()
        table_lib.set('insert', self._table_insert)
        table_lib.set('remove', self._table_remove)
        table_lib.set('concat', self._table_concat)
        return table_lib

    def _create_string_library(self):
        string_lib = LuaTable()
        string_lib.set('len', lambda s: len(self._tostring(s)))
        string_lib.set('sub', self._string_sub)
        string_lib.set('find', self._string_find)
        string_lib.set('format', self._string_format)
        string_lib.set('upper', lambda s: self._tostring(s).upper())
        string_lib.set('lower', lambda s: self._tostring(s).lower())
        return string_lib

    def _builtin_print(self, *args):
        """Lua's print function"""
        parts = []
        for arg in args:
            parts.append(self._tostring(arg))
        print('\t'.join(parts))
        return None

    def _builtin_type(self, obj):
        """Lua's type function"""
        if isinstance(obj, LuaNil):
            return 'nil'
        elif isinstance(obj, LuaBool):
            return 'boolean'
        elif isinstance(obj, (int, float)):
            return 'number'
        elif isinstance(obj, str):
            return 'string'
        elif isinstance(obj, LuaTable):
            return 'table'
        elif isinstance(obj, LuaFunction) or callable(obj):
            return 'function'
        else:
            return 'userdata'

    def _builtin_tonumber(self, obj, base=10):
        """Lua's tonumber function"""
        try:
            if isinstance(obj, (int, float)):
                return obj
            s = self._tostring(obj)
            if isinstance(base, int) and base != 10:
                return int(s, base)
            else:
                if '.' in s or 'e' in s.lower():
                    return float(s)
                return int(s)
        except:
            return LuaNil()

    def _builtin_tostring(self, obj):
        """Lua's tostring function"""
        return self._tostring(obj)

    def _tonumber(self, obj):
        """Convert to number (internal helper)"""
        if isinstance(obj, (int, float)):
            return obj
        elif isinstance(obj, str):
            try:
                if '.' in obj or 'e' in obj.lower():
                    return float(obj)
                return int(obj)
            except:
                return 0
        else:
            return 0

    def _tostring(self, obj):
        """Convert to string"""
        if isinstance(obj, LuaNil):
            return 'nil'
        elif isinstance(obj, LuaBool):
            return 'true' if obj.value else 'false'
        elif isinstance(obj, (int, float)):
            if isinstance(obj, float) and obj == int(obj):
                return str(int(obj))
            return str(obj)
        elif isinstance(obj, str):
            return obj
        elif isinstance(obj, LuaTable):
            return 'table'
        elif isinstance(obj, LuaFunction) or callable(obj):
            return 'function'
        else:
            return str(obj)

    def _builtin_assert(self, value, message=None):
        if not self._is_truthy(value):
            if message:
                raise RuntimeError(self._tostring(message))
            else:
                raise RuntimeError("assertion failed!")
        return value

    def _builtin_pairs(self, table):
        """Lua's pairs iterator"""
        if not isinstance(table, LuaTable):
            raise TypeError("pairs() requires a table")
        return iter(table.items())

    def _builtin_ipairs(self, table):
        """Lua's ipairs iterator"""
        if not isinstance(table, LuaTable):
            raise TypeError("ipairs() requires a table")
        return iter([(i, v) for i, v in enumerate(table.list, 1)])

    def _builtin_next(self, table, key=None):
        if not isinstance(table, LuaTable):
            return LuaNil()
        # Simplified
        return LuaNil()

    def _builtin_rawget(self, table, key):
        if isinstance(table, LuaTable):
            return table.get(key)
        return LuaNil()

    def _builtin_rawset(self, table, key, value):
        if isinstance(table, LuaTable):
            table.set(key, value)
        return table

    def _builtin_setmetatable(self, table, metatable):
        # Simplified - just return the table
        return table

    def _builtin_getmetatable(self, table):
        return LuaNil()

    def _builtin_error(self, message=""):
        raise RuntimeError(self._tostring(message))

    def _builtin_select(self, *args):
        # Simplified
        return args

    def _builtin_unpack(self, table):
        if isinstance(table, LuaTable):
            return tuple(table.list)
        return ()

    def _table_insert(self, table, value, pos=None):
        if isinstance(table, LuaTable):
            if pos is None:
                table.list.append(value)
            else:
                pos = int(self._tonumber(pos))
                table.list.insert(pos - 1, value)
        return LuaNil()

    def _table_remove(self, table, pos=None):
        if isinstance(table, LuaTable) and len(table.list) > 0:
            if pos is None:
                return table.list.pop()
            else:
                pos = int(self._tonumber(pos))
                if 1 <= pos <= len(table.list):
                    return table.list.pop(pos - 1)
        return LuaNil()

    def _table_concat(self, table, sep="", i=1, j=None):
        if not isinstance(table, LuaTable):
            return ""
        sep = self._tostring(sep)
        i = int(self._tonumber(i))
        j = j if j else len(table.list)
        j = int(self._tonumber(j))
        parts = []
        for idx in range(i, j + 1):
            if 1 <= idx <= len(table.list):
                parts.append(self._tostring(table.list[idx - 1]))
        return sep.join(parts)

    def _string_sub(self, s, i, j=None):
        s = self._tostring(s)
        i = int(self._tonumber(i))
        if j is None:
            j = len(s)
        else:
            j = int(self._tonumber(j))

        # Lua uses 1-based indexing, handle negative indices
        if i < 0:
            i = len(s) + i + 1
        if j < 0:
            j = len(s) + j + 1

        return s[i-1:j]

    def _string_find(self, s, pattern, init=1):
        s = self._tostring(s)
        pattern = self._tostring(pattern)
        init = int(self._tonumber(init))

        pos = s.find(pattern, init - 1)
        if pos >= 0:
            return pos + 1, pos + len(pattern)
        return LuaNil()

    def _string_format(self, format_str, *args):
        format_str = self._tostring(format_str)
        # Simple implementation - just handle %s, %d, %f
        result = format_str
        for arg in args:
            if '%s' in result:
                result = result.replace('%s', self._tostring(arg), 1)
            elif '%d' in result:
                result = result.replace('%d', str(int(self._tonumber(arg))), 1)
            elif '%f' in result:
                result = result.replace('%f', str(float(self._tonumber(arg))), 1)
        return result

    def _is_truthy(self, value):
        """Check if a value is truthy in Lua"""
        return not (isinstance(value, LuaNil) or (isinstance(value, LuaBool) and not value.value))

    def interpret(self, node):
        """Interpret an AST node"""
        if isinstance(node, Chunk):
            result = None
            for stmt in node.statements:
                result = self.interpret(stmt)
                if self.should_return or self.should_break:
                    break
            return result

        elif isinstance(node, Number):
            return node.value

        elif isinstance(node, String):
            return node.value

        elif isinstance(node, Bool):
            return LuaBool(node.value)

        elif isinstance(node, Nil):
            return LuaNil()

        elif isinstance(node, Var):
            return self._get_variable(node.name)

        elif isinstance(node, Table):
            table = LuaTable()
            index = 1
            for key, value in node.fields:
                val = self.interpret(value) if value else LuaNil()
                if key is None:
                    table.set(index, val)
                    index += 1
                else:
                    key_val = self.interpret(key)
                    table.set(key_val, val)
            return table

        elif isinstance(node, BinOp):
            left = self.interpret(node.left)
            right = self.interpret(node.right)
            return self._apply_binop(node.op, left, right)

        elif isinstance(node, UnaryOp):
            operand = self.interpret(node.operand)
            return self._apply_unaryop(node.op, operand)

        elif isinstance(node, IndexAccess):
            obj = self.interpret(node.obj)
            index = self.interpret(node.index)

            if isinstance(obj, LuaTable):
                if isinstance(index, str):
                    return obj.get(index)
                else:
                    index_num = int(self._tonumber(index)) if not isinstance(index, int) else index
                    return obj.get(index_num)
            elif isinstance(obj, str):
                # String indexing
                if isinstance(index, int):
                    if 1 <= index <= len(obj):
                        return obj[index - 1]
                else:
                    index_num = int(self._tonumber(index))
                    if 1 <= index_num <= len(obj):
                        return obj[index_num - 1]
                return LuaNil()
            return LuaNil()

        elif isinstance(node, Assignment):
            values = [self.interpret(v) for v in node.values]

            # Pad with nil if needed
            while len(values) < len(node.targets):
                values.append(LuaNil())

            for target, value in zip(node.targets, values):
                if isinstance(target, Var):
                    self._set_variable(target.name, value)
                elif isinstance(target, IndexAccess):
                    obj = self.interpret(target.obj)
                    index = self.interpret(target.index)
                    if isinstance(obj, LuaTable):
                        obj.set(index, value)

            return values[0] if values else LuaNil()

        elif isinstance(node, LocalAssignment):
            values = [self.interpret(v) for v in node.values]
            while len(values) < len(node.names):
                values.append(LuaNil())

            for name, value in zip(node.names, values):
                self.locals_stack[-1][name] = value

            return LuaNil()

        elif isinstance(node, IfStatement):
            condition = self.interpret(node.condition)
            if self._is_truthy(condition):
                return self.interpret(Chunk(node.then_block))

            for elif_cond, elif_body in node.elif_blocks:
                condition = self.interpret(elif_cond)
                if self._is_truthy(condition):
                    return self.interpret(Chunk(elif_body))

            if node.else_block:
                return self.interpret(Chunk(node.else_block))

            return LuaNil()

        elif isinstance(node, WhileStatement):
            result = LuaNil()
            while self._is_truthy(self.interpret(node.condition)):
                result = self.interpret(Chunk(node.body))
                if self.should_break:
                    self.should_break = False
                    break
                if self.should_return:
                    break
            return result

        elif isinstance(node, ForStatement):
            start = int(self._tonumber(self.interpret(node.start)))
            end = int(self._tonumber(self.interpret(node.end)))
            step = int(self._tonumber(self.interpret(node.step)))

            result = LuaNil()

            if step > 0:
                i = start
                while i <= end:
                    self._set_variable(node.var, i)
                    result = self.interpret(Chunk(node.body))
                    if self.should_break:
                        self.should_break = False
                        break
                    if self.should_return:
                        break
                    i += step
            else:
                i = start
                while i >= end:
                    self._set_variable(node.var, i)
                    result = self.interpret(Chunk(node.body))
                    if self.should_break:
                        self.should_break = False
                        break
                    if self.should_return:
                        break
                    i += step

            return result

        elif isinstance(node, ForInStatement):
            # Get the iterator expressions
            iter_values = [self.interpret(expr) for expr in node.expressions]

            # For ipairs/pairs, the first value should be the table
            table = iter_values[0]
            result = LuaNil()

            if isinstance(table, LuaTable):
                # Check if we have an iterator function (for pairs)
                if callable(table):
                    # It's a generator/iterator function
                    try:
                        for values in table:
                            # Unpack values to loop variables
                            for var, val in zip(node.vars, values):
                                self._set_variable(var, val)
                            result = self.interpret(Chunk(node.body))
                            if self.should_break:
                                self.should_break = False
                                break
                            if self.should_return:
                                break
                    except TypeError:
                        pass
                elif hasattr(table, '__iter__'):
                    # It's iterable (from ipairs/pairs)
                    try:
                        for items in table:
                            # items should be (key, value) or similar
                            if isinstance(items, tuple):
                                for var, val in zip(node.vars, items):
                                    self._set_variable(var, val)
                            else:
                                self._set_variable(node.vars[0], items)
                            result = self.interpret(Chunk(node.body))
                            if self.should_break:
                                self.should_break = False
                                break
                            if self.should_return:
                                break
                    except (TypeError, StopIteration):
                        pass

            return result

        elif isinstance(node, FunctionDef):
            func = LuaFunction(node.params, node.varargs, node.body, self.locals_stack[-1].copy())
            if node.name:
                self._set_variable(node.name, func)
            return func

        elif isinstance(node, FunctionCall):
            func = self.interpret(node.func)
            args = [self.interpret(arg) for arg in node.args]
            return self._call_function(func, args)

        elif isinstance(node, MethodCall):
            obj = self.interpret(node.obj)
            method_name = node.method
            args = [self.interpret(arg) for arg in node.args]

            if isinstance(obj, LuaTable):
                method = obj.get(method_name)
                args = [obj] + args
                return self._call_function(method, args)

            return LuaNil()

        elif isinstance(node, ReturnStatement):
            self.should_return = True
            self.return_values = [self.interpret(v) for v in node.values]
            return self.return_values[0] if self.return_values else LuaNil()

        elif isinstance(node, BreakStatement):
            self.should_break = True
            return LuaNil()

        elif isinstance(node, DoBlock):
            return self.interpret(Chunk(node.body))

        return LuaNil()

    def _get_variable(self, name):
        """Get a variable from the environment"""
        # Search from innermost to outermost scope
        for scope in reversed(self.locals_stack):
            if name in scope:
                return scope[name]

        # Check globals
        if name in self.globals:
            return self.globals[name]

        return LuaNil()

    def _set_variable(self, name, value):
        """Set a variable in the appropriate scope"""
        # If it exists in a local scope, update it there
        for scope in reversed(self.locals_stack):
            if name in scope:
                scope[name] = value
                return

        # Otherwise set in globals
        self.globals[name] = value

    def _apply_binop(self, op, left, right):
        """Apply a binary operator"""
        if op == '+':
            return self._tonumber(left) + self._tonumber(right)
        elif op == '-':
            return self._tonumber(left) - self._tonumber(right)
        elif op == '*':
            return self._tonumber(left) * self._tonumber(right)
        elif op == '/':
            return self._tonumber(left) / self._tonumber(right)
        elif op == '//':
            return int(self._tonumber(left) // self._tonumber(right))
        elif op == '%':
            return self._tonumber(left) % self._tonumber(right)
        elif op == '^':
            return self._tonumber(left) ** self._tonumber(right)
        elif op == '==':
            return LuaBool(self._values_equal(left, right))
        elif op == '~=':
            return LuaBool(not self._values_equal(left, right))
        elif op == '<':
            return LuaBool(self._tonumber(left) < self._tonumber(right))
        elif op == '>':
            return LuaBool(self._tonumber(left) > self._tonumber(right))
        elif op == '<=':
            return LuaBool(self._tonumber(left) <= self._tonumber(right))
        elif op == '>=':
            return LuaBool(self._tonumber(left) >= self._tonumber(right))
        elif op == 'and':
            return right if self._is_truthy(left) else left
        elif op == 'or':
            return left if self._is_truthy(left) else right
        elif op == '..':
            return self._tostring(left) + self._tostring(right)
        else:
            return LuaNil()

    def _apply_unaryop(self, op, operand):
        """Apply a unary operator"""
        if op == '-':
            return -self._tonumber(operand)
        elif op == 'not':
            return LuaBool(not self._is_truthy(operand))
        elif op == '#':
            if isinstance(operand, LuaTable):
                return operand.length()
            elif isinstance(operand, str):
                return len(operand)
            else:
                return 0
        else:
            return LuaNil()

    def _values_equal(self, left, right):
        """Check if two values are equal"""
        if type(left) != type(right):
            return False
        if isinstance(left, LuaNil):
            return True
        elif isinstance(left, LuaBool):
            return left.value == right.value
        elif isinstance(left, (int, float)):
            return left == right
        elif isinstance(left, str):
            return left == right
        elif isinstance(left, LuaTable):
            return left is right
        else:
            return left is right

    def _call_function(self, func, args):
        """Call a Lua function"""
        if callable(func) and not isinstance(func, LuaFunction):
            # Built-in function
            try:
                return func(*args)
            except TypeError:
                return func(*args[:func.__code__.co_argcount])

        elif isinstance(func, LuaFunction):
            # User-defined function
            # Create new local scope
            new_scope = func.closure.copy()

            # Bind parameters
            for i, param in enumerate(func.params):
                if i < len(args):
                    new_scope[param] = args[i]
                else:
                    new_scope[param] = LuaNil()

            # Handle varargs
            if func.varargs:
                varargs_table = LuaTable()
                for i, arg in enumerate(args[len(func.params):], 1):
                    varargs_table.set(i, arg)
                new_scope['arg'] = varargs_table

            # Push new scope
            self.locals_stack.append(new_scope)
            self.should_return = False
            self.return_values = []

            # Execute function body
            self.interpret(Chunk(func.body))

            # Pop scope
            self.locals_stack.pop()

            # Return values
            result = self.return_values[0] if self.return_values else LuaNil()
            self.should_return = False
            self.return_values = []

            return result

        else:
            raise TypeError(f"Cannot call {type(func)}")

def print_usage():
    print("usage:", sys.argv[0], "[options] [script [args]]")
    print("Available options are:")
    print("  -e stat   execute string 'stat'")
    print("  -i        enter interactive mode after executing 'script'")
    print("  -l mod    require library 'mod' into global 'mod'")
    print("  -l g=mod  require library 'mod' into global 'g'")
    print("  -v        show version information")
    print("  -E        ignore environment variables")
    print("  -W        turn warnings on")
    print("  --        stop handling options")
    print("  -         stop handling options and execute stdin")

def main():
