class Token:
    def __init__(self, type_, value, line=1, col=1):
        self.type = type_
        self.value = value
        self.line = line
        self.col = col

    def __repr__(self):
        return f"Token({self.type}, {repr(self.value)})"

class Lexer:
    """Tokenizes Lua source code"""

    KEYWORDS = {
        'and', 'break', 'do', 'else', 'elseif', 'end',
        'false', 'for', 'function', 'goto', 'if', 'in',
        'local', 'nil', 'not', 'or', 'repeat', 'return',
        'then', 'true', 'until', 'while'
    }

    def __init__(self, source):
        self.source = source
        self.pos = 0
        self.line = 1
        self.col = 1
        self.tokens = []
        self.tokenize()

    def peek(self, offset=0):
        pos = self.pos + offset
        if pos < len(self.source):
            return self.source[pos]
        return None

    def advance(self):
        if self.pos < len(self.source):
            ch = self.source[self.pos]
            self.pos += 1
            if ch == '\n':
                self.line += 1
                self.col = 1
            else:
                self.col += 1
            return ch
        return None

    def skip_whitespace(self):
        while self.peek() and self.peek() in ' \t\n\r':
            self.advance()

    def skip_comment(self):
        if self.peek() == '-' and self.peek(1) == '-':
            # Single line comment
            self.advance()  # -
            self.advance()  # -
            while self.peek() and self.peek() != '\n':
                self.advance()
            if self.peek() == '\n':
                self.advance()
            return True
        return False

    def read_string(self, quote):
        """Read a string literal"""
        self.advance()  # consume opening quote
        result = ""
        while True:
            ch = self.peek()
            if ch is None:
                raise SyntaxError(f"Unterminated string at line {self.line}")
            if ch == quote:
                self.advance()
                break
            if ch == '\\':
                self.advance()
                next_ch = self.peek()
                if next_ch == 'n':
                    result += '\n'
                    self.advance()
                elif next_ch == 't':
                    result += '\t'
                    self.advance()
                elif next_ch == 'r':
                    result += '\r'
                    self.advance()
                elif next_ch == '\\':
                    result += '\\'
                    self.advance()
                elif next_ch == quote:
                    result += quote
                    self.advance()
                else:
                    result += next_ch
                    self.advance()
            else:
                result += ch
                self.advance()
